WITH filtered_inventory AS (SELECT * FROM inventory WHERE (product_id IN (5, 6, 7, 10) AND store_id = 2) OR last_restock <= '2025-02-01'), inventory_stats AS (SELECT DATE_TRUNC('MONTH', last_restock) AS last_restock_month, MAX(quantity) - MIN(quantity) AS quantity_range FROM filtered_inventory GROUP BY DATE_TRUNC('MONTH', last_restock)) SELECT last_restock_month, quantity_range FROM inventory_stats WHERE quantity_range >= 50 ORDER BY 2, last_restock_month LIMIT 10
